import json, os, hashlib, stat
base=os.environ['STAMPED_JUDGE_TARGET']
manifest=json.load(open(os.environ['STAMPED_OPERATIONAL_MANIFEST']))
root=os.path.dirname(base)
expected={e['path']:e for e in manifest['entries']}
actual=set()
for dp,ds,fs in os.walk(base,followlinks=False):
 relroot=os.path.relpath(dp,root)
 actual.add(relroot)
 for name in ds+fs:
  p=os.path.join(dp,name); rel=os.path.relpath(p,root); actual.add(rel)
  if os.path.islink(p): kind='symlink'; value=os.readlink(p)
  elif os.path.isdir(p): kind='directory'; value=None
  else: kind='file'; h=hashlib.sha256();
  if kind=='file':
   with open(p,'rb') as f:
    for b in iter(lambda:f.read(1024*1024),b''): h.update(b)
   value=h.hexdigest()
  e=expected.get(rel)
  if not e: print('EXTRA',rel,kind)
  elif e['kind']!=kind or (kind=='file' and e.get('sha256')!=value) or (kind=='symlink' and e.get('target')!=value): print('DIFF',rel,kind,value,e)
for rel in sorted(set(expected)-actual): print('MISSING',rel)
print('entries_expected',len(expected),'entries_seen',len(actual),'capture',manifest['kind'])
